import json

# Factorization: 32x^3 - 8xy^2 = 8x(2x - y)(2x + y)
def poly(x, y):
    return 32 * x**3 - 8 * x * y**2

def factored(x, y):
    return (8 * x) * (2 * x - y) * (2 * x + y)

# Verify the factorization identity on a finite grid of integer points
identity_ok = all(
    poly(x, y) == factored(x, y)
    for x in range(-10, 11)
    for y in range(-10, 11)
)

x, y = 10, 10
factors = [8 * x, 2 * x - y, 2 * x + y]

if identity_ok:
    password = "".join(str(f) for f in factors)
    print(json.dumps({
        "final_answer": password,
        "evidence": {
            "factorization": "8x(2x-y)(2x+y)",
            "identity_verified_on_grid": identity_ok,
            "factor_values": factors,
            "product_check": factors[0] * factors[1] * factors[2] == poly(x, y),
        },
    }))
else:
    print("UNSUPPORTED")
